    try {
      const p = new Parser(lines[ln])
      p.ws()
      const c = p.s[p.i]
      if (c === undefined || c === '#' || c === ';') continue
      if (c === '[') {
        const aot = p.s[p.i + 1] === '['
        p.i += aot ? 2 : 1
        p.ws()
        const keys = p.dotted()
        p.ws()
        if (p.s[p.i] !== ']') fail('unterminated table header')
        p.i++
        if (aot) {
          if (p.s[p.i] !== ']') fail('unterminated table header')
          p.i++
        }
        p.ws()
        if (!p.atEnd()) fail('trailing text after a table header')
        const parent = walk(root, keys, keys.length - 1)
        const last = keys[keys.length - 1]
        const full = keys.join('.')
        const n = parent.map.get(last)
        if (aot) {
          const t = new Table()
          if (n === undefined) { const a = new Arr(true); a.items.push(t); parent.map.set(last, a) } else if (n instanceof Arr && n.aot) n.items.push(t)
          else fail(full + ' is not an array of tables')
          cur = t
        } else {
          if (n === undefined) { const t = new Table(); t.header = true; parent.map.set(last, t); cur = t } else if (n instanceof Table) {
            if (n.header) fail(`table ${full} is defined twice`)
            n.header = true
            cur = n
          } else fail(full + ' is not a table')
        }
        curPath = keys
        continue
      }
      const keys = p.dotted()
      p.ws()
      if (p.s[p.i] !== '=') fail('expected key = value')
      p.i++
      const prefix = curPath.concat(keys.slice(0, -1))
      const v = p.value(curPath.concat(keys))
      p.ws()
      if (!p.atEnd()) fail('trailing text after a value')
      assign(cur, curPath, keys, v)
    } catch (e) {
      if (e instanceof Fail) throw new Fail(`line ${ln + 1}: ${e.message}`)
      throw e
    }
  }
  return root
}

const cmp = (a, b) => {
  const x = Array.from(a, (ch) => ch.codePointAt(0))
  const y = Array.from(b, (ch) => ch.codePointAt(0))
  for (let i = 0; i < Math.min(x.length, y.length); i++) if (x[i] !== y[i]) return x[i] - y[i]
  return x.length - y.length
}
const sortedKeys = (t) => [...t.map.keys()].sort(cmp)

function toJson(n, ind) {
  const pad = '  '.repeat(ind + 1)
  const end = '  '.repeat(ind)
  if (n instanceof Table) {
    const ks = sortedKeys(n)
    if (!ks.length) return '{}'
    return '{\n' + ks.map((k) => `${pad}${JSON.stringify(k)}: ${toJson(n.map.get(k), ind + 1)}`).join(',\n') + '\n' + end + '}'
  }
  if (n instanceof Arr) {
    if (!n.items.length) return '[]'
    return '[\n' + n.items.map((v) => pad + toJson(v, ind + 1)).join(',\n') + '\n' + end + ']'
  }
  if (n.type === 'integer') return n.value
  return JSON.stringify(n.value)
}

function typeOf(n) {
  if (n instanceof Table) return 'table'
  if (n instanceof Arr) return 'array'
  return n.type
}

function keyLines(n, path, out) {
  if (n instanceof Table) {
    for (const k of sortedKeys(n)) {
      const p = path === null ? k : path + '.' + k
      const v = n.map.get(k)
      out.push(`${p} ${typeOf(v)}`)
      keyLines(v, p, out)
    }
  } else if (n instanceof Arr) {
    n.items.forEach((v, i) => {
      const p = `${path}[${i}]`
      out.push(`${p} ${typeOf(v)}`)
      keyLines(v, p, out)
    })
  }
}

const mode = process.argv[2]
if (process.argv.length !== 3 || (mode !== 'json' && mode !== 'keys')) {
  process.stderr.write('error: usage: cli.js json|keys\n')
  process.exit(2)
}
let root
try {
  root = parse(readFileSync(0, 'utf8'))
} catch (e) {
  if (!(e instanceof Fail)) throw e
  process.stderr.write(`error: ${e.message}\n`)
  process.exit(2)
}
if (mode === 'json') process.stdout.write(toJson(root, 0) + '\n')
else {
  const out = []
  keyLines(root, null, out)
  process.stdout.write(out.map((l) => l + '\n').join(''))
}
"}

